from django.contrib.auth import authenticate, login, logout
from django.contrib.auth.decorators import login_required
from django.contrib.auth.models import User
from django.contrib import messages
from django.core.urlresolvers import reverse
from django.http import HttpResponseRedirect
from django.shortcuts import render_to_response
from django.template import RequestContext
from urllib import urlencode

def home_page(request):
    if not request.user.is_authenticated():
        return HttpResponseRedirect(reverse('account.views.login_page',
            args=[]))
    return render_to_response('home.html', {},
            context_instance=RequestContext(request))

@login_required
def management(request):
    return render_to_response('account/management.html', {},
            context_instance=RequestContext(request))

def login_page(request):
    if request.user.is_authenticated():
        return HttpResponseRedirect(reverse('account.views.home_page',
                args=[]))
    return render_to_response('login.html', { 'redirect_to': request.GET.get('next')},
        context_instance=RequestContext(request))

def auth(request):
    username = request.REQUEST.get('username')
    password = request.REQUEST.get('password')
    user = authenticate(username=username, password=password)
    redirect_to = request.REQUEST.get('next')
    if user is not None:
        messages.info(request, "Logged in as %s" % username)
        login(request, user)
        return HttpResponseRedirect(redirect_to)
    else:
        messages.error(request, "Could not log you in as %s" % username)
    return HttpResponseRedirect("%s?%s" % (reverse('account.views.login_page',
        args=[]), urlencode(dict(next=redirect_to)) ) )

def change_password(request):
    if not request.user.check_password(request.REQUEST.get("currentPassword")):
        messages.error(request, "Incorrect password")
    elif request.REQUEST.get("newPassword") != \
            request.REQUEST.get("newPasswordVerification"):
        messages.error(request, "Passwords don't match")
    elif len(request.REQUEST.get("newPassword")) < 3:
        messages.error(request, "Password too short")
    else:
        u = User.objects.get(id=request.user.id)
        u.set_password(request.REQUEST.get("newPassword"))
        u.save()
        messages.success(request, "Successfully changed password")
    return HttpResponseRedirect(reverse('account.views.home_page', args=[]))

def logout_page(request):
    logout(request)
    messages.info(request, "Successfully logged out")
    return HttpResponseRedirect(reverse('account.views.login_page',
        args=[]))

"""Shim to install packages using flit metadata on Python 2
"""

import argparse
import configparser
import os
import shutil
import site
from subprocess import check_call
import sys
import tempfile

pjoin = os.path.join

__version__ = '0.1'

class Module(object):
    """This represents the module/package that we are going to distribute
    """
    def __init__(self, name, directory='.'):
        self.name = name

        # It must exist either as a .py file or a directory, but not both
        pkg_dir = pjoin(directory, name)
        py_file = pjoin(directory, name+'.py')
        if os.path.isdir(pkg_dir) and os.path.isfile(py_file):
            raise ValueError("Both {} and {} exist".format(pkg_dir, py_file))
        elif os.path.isdir(pkg_dir):
            self.path = pkg_dir
            self.is_package = True
        elif os.path.isfile(py_file):
            self.path = py_file
            self.is_package = False
        else:
            raise ValueError("No file/folder found for module {}".format(name))

    @property
    def file(self):
        if self.is_package:
            return pjoin(self.path, '__init__.py')
        else:
            return self.path

# For the directories where we'll install stuff
_interpolation_vars = {
    'userbase': site.USER_BASE,
    'usersite': site.USER_SITE,
    'py_major': sys.version_info[0],
    'py_minor': sys.version_info[1],
    'prefix'  : sys.prefix,
}

def _requires_dist_to_pip_requirement(requires_dist):
    """Parse "Foo (v); python_version == '2.x'" from Requires-Dist

    Returns pip-style appropriate for requirements.txt.
    """
    env_mark = ''
    if ';' in requires_dist:
        name_version, env_mark = requires_dist.split(';', 1)
    else:
        name_version = requires_dist
    if '(' in name_version:
        # turn 'name (X)' and 'name (<X.Y)'
        # into 'name == X' and 'name < X.Y'
        name, version = name_version.split('(', 1)
        name = name.strip()
        version = version.replace(')', '').strip()
        if not any(c in version for c in '=<>'):
            version = '==' + version
        name_version = name + version
    # re-add environment marker
    return ';'.join([name_version, env_mark])

def get_dirs(user=True):
    """Get the 'scripts' and 'purelib' directories we'll install into.

    This is an abbreviated version of distutils.command.install.INSTALL_SCHEMES
    """
    if user:
        purelib = site.USER_SITE
        if sys.platform == 'win32':
            scripts = "{userbase}/Python{py_major}{py_minor}/Scripts"
        else:
            scripts = "{userbase}/bin"
    elif sys.platform == 'win32':
        scripts = "{prefix}/Scripts",
        purelib = "{prefix}/Lib/site-packages"
    else:
        scripts = "{prefix}/bin"
        purelib = "{prefix}/lib/python{py_major}.{py_minor}/site-packages"

    return {
        'scripts': scripts.format(**_interpolation_vars),
        'purelib': purelib.format(**_interpolation_vars),
    }

script_template = """\
#!{interpreter}
from {module} import {func}
if __name__ == '__main__':
    {func}()
"""

class RootInstallError(Exception):
    def __str__(self):
        return ("Installing packages as root is not recommended. "
            "To allow this, set FLIT_ROOT_INSTALL=1 and try again.")


class Installer(object):
    def __init__(self, ini_path, user=None):
        self.cfg = configparser.ConfigParser()
        self.cfg.read([ini_path])
        self.module = Module(self.cfg.get('metadata', 'module'))

        if user is None:
            self.user = site.ENABLE_USER_SITE
        else:
            self.user = user

        if (os.getuid() == 0) and (not os.environ.get('FLIT_ROOT_INSTALL')):
            raise RootInstallError

    def install_scripts(self, script_defs, scripts_dir):
        for name, ep in script_defs.items():
            module, func = ep.split(':', 1)
            script_file = pjoin(scripts_dir, name)
            with open(script_file, 'w') as f:
                f.write(script_template.format(
                    interpreter=sys.executable,
                    module=module,
                    func=func
                ))
            os.chmod(script_file, 0o755)

            if sys.platform == 'win32':
                cmd_file = script_file.with_suffix('.cmd')
                cmd = '"{python}" "%~dp0\{script}" %*\r\n'.format(
                            python=sys.executable, script=name)

                with open(cmd_file, 'w') as f:
                    f.write(cmd)

    def install_requirements(self):
        """Install requirements of a package with pip.

        Creates a temporary requirements.txt from requires_dist metadata.
        """
         # construct the full list of requirements, including dev requirements
        requires_dist = self.cfg.get('metadata', 'requires', fallback='').splitlines()
        dev_requires = self.cfg.get('metadata', 'dev-requires', fallback='').splitlines()
        requirements = requires_dist + dev_requires

        if not requirements:
            return

        requirements = [
            _requires_dist_to_pip_requirement(req_d)
            for req_d  in requirements
        ]
        cmd = [sys.executable, '-m', 'pip', 'install']
        if self.user:
            cmd.append('--user')
        with tempfile.NamedTemporaryFile(mode='w',
                                         suffix='requirements.txt',
                                         delete=False) as tf:
            tf.file.write('\n'.join(requirements))
        cmd.extend(['-r', tf.name])
        try:
            check_call(cmd)
        finally:
            os.remove(tf.name)

    def install(self):
        """Install a module/package into site-packages, and create its scripts.
        """
        dirs = get_dirs(user=self.user)
        try:
            os.makedirs(dirs['purelib'])
        except OSError:
            pass

        try:
            os.makedirs(dirs['scripts'])
        except OSError:
            pass

        dst = os.path.join(dirs['purelib'], os.path.basename(self.module.path))
        if os.path.lexists(dst):
            if os.path.isdir(dst) and not os.path.islink(dst):
                shutil.rmtree(dst)
            else:
                os.unlink(dst)

        self.install_requirements()

        src = self.module.path
        if os.path.isdir(self.module.path):
            shutil.copytree(src, dst)
        else:
            shutil.copy2(src, dst)

        if 'scripts' in self.cfg:
            scripts = self.cfg['scripts']
            self.install_scripts(scripts, dirs['scripts'])

def main():
    ap = argparse.ArgumentParser('flit-install-py2', version=__version__)
    ap.add_argument('-f', '--ini-file', default='flit.ini')
    opts = ap.parse_args()

    Installer(opts.ini_file).install()

if __name__ == '__main__':
    main()

import uuid

from django import forms
from django.contrib.auth import get_user_model, password_validation
from django.contrib.auth.hashers import make_password
from django.contrib.auth.tokens import default_token_generator
from django.core.exceptions import ValidationError
from django.db import DatabaseError, transaction
from django.db.models import Q
from django.shortcuts import redirect
from django.urls import reverse
from django.utils.encoding import force_bytes
from django.utils.http import urlsafe_base64_encode

# noinspection PyUnresolvedReferences
from phonenumber_field.formfields import PhoneNumberField

from phone_auth.validators import validate_username

from . import app_settings
from .models import EmailAddress, PhoneNumber
from .signals import (
    reset_password_email,
    reset_password_phone,
    verify_email,
    verify_phone,
)
from .tokens import phone_token_generator

User = get_user_model()


class PhoneRegisterForm(forms.Form):
    """Form for user registration"""

    phone = PhoneNumberField()
    username = forms.CharField(
        required=app_settings.REGISTER_USERNAME_REQUIRED, validators=[validate_username]
    )
    email = forms.EmailField(required=app_settings.REGISTER_EMAIL_REQUIRED)
    first_name = forms.CharField(required=app_settings.REGISTER_FNAME_REQUIRED)
    last_name = forms.CharField(required=app_settings.REGISTER_LNAME_REQUIRED)
    password = forms.CharField(widget=forms.PasswordInput())
    confirm_password = forms.CharField(
        widget=forms.PasswordInput(),
        required=app_settings.REGISTER_CONFIRM_PASSWORD_REQUIRED,
    )

    def clean(self):
        errors = {}
        if app_settings.REGISTER_CONFIRM_PASSWORD_REQUIRED:
            if self.cleaned_data.get("password") != self.cleaned_data.get(
                "confirm_password"
            ):
                errors["confirm_password"] = "Password didn't match"
        if self.cleaned_data.get("email", None) is not None:
            if EmailAddress.objects.filter(
                email__iexact=self.cleaned_data.get("email")
            ).exists():
                errors["email"] = "Email already exists"
        if self.cleaned_data.get("phone", None) is not None:
            if PhoneNumber.objects.filter(
                phone=self.cleaned_data.get("phone")
            ).exists():
                errors["phone"] = "Phone already exists"
        if self.cleaned_data.get("username", None) is not None:
            if User.objects.filter(
                username__exact=self.cleaned_data.get("username")
            ).exists():
                errors["username"] = "Username already exists"

        if errors:
            raise ValidationError(errors)

    def _post_clean(self):
        super()._post_clean()
        # Validate the password after self.instance is updated with form data
        # by super().
        password = self.cleaned_data.get("password")
        user_data = dict(self.cleaned_data)
        if "phone" in user_data:
            user_data.pop("phone")
        if "confirm_password" in user_data:
            user_data.pop("confirm_password")
        user_instance = User(**user_data)

        try:
            password_validation.validate_password(password, user=user_instance)
        except ValidationError as error:
            self.add_error("password", error)

    def save(self):
        try:
            phone = self.cleaned_data.get("phone", None)
            if phone is not None:
                self.cleaned_data.pop("phone")

            if "confirm_password" in self.cleaned_data:
                self.cleaned_data.pop("confirm_password")

            username = self.cleaned_data.get("username")
            if not username:
                self.cleaned_data["username"] = uuid.uuid4().hex

            email = self.cleaned_data.get("email", None)

            self.cleaned_data["password"] = make_password(self.cleaned_data["password"])

            with transaction.atomic():
                user = User.objects.create(**self.cleaned_data)
                if phone is not None:
                    PhoneNumber.objects.create(user=user, phone=phone)
                if email is not None:
                    EmailAddress.objects.create(user=user, email=email)
        except DatabaseError as e:
            if "UNIQUE constraint" in e.args[0]:
                if "phone" in e.args[0]:
                    self.add_error("phone", "Phone already exists")
                if "username" in e.args[0]:
                    self.add_error("username", "Username already exists")
                if "email" in e.args[0]:
                    self.add_error("email", "Email already exists")


