        if matched == 6:
            result = '1등입니다!'
        elif matched == 5:              # 보너스 넘버..!
            if lotto_info['bnusNo'] in lotto_numbers:
                result = '2등입니다!'
            else:
                result = '3등입니다!'
        elif matched == 4:
            result = '4등입니다.'
        elif matched == 3:
            result = '5등입니다...'
        else:
            result = '꽝입니다........8ㅅ8'
    else:
        result = '입력하신 숫자가 6개가 아닙니다.'

    return render_template('lotto_result.html', result=result)





