                text += f'\n{bar}: Price = {bars[bar][0].c}, Time = {bars[bar][0].t}'
            reply_private(request, text)
        except Exception as e:
            reply_private(request, f"ERROR: {str(e)}")
    asyncio.run(sub_get_price(api, request, args))
    return ""

