def send_film_opinion(request, id, txt, eye, heart, mind, nick, oid=False):
    try:
        profile = request.profile

        txt = BeautifulSoup(txt.strip(), from_encoding="utf-8").text
        txt = escape(txt)

        oid = False if oid == 'False' else oid
