# 10進-->2進変換 (整数部, 小数部それぞれ8bit)
def dectobin(target):
    # target を整数部と小数部に分ける
    i = int(target)
    f = target - i

    # 整数部を2進数に変換する
    a = []      # 余りを入れるリスト=2進の整数部
    c = []      # 商を入れるリスト
    n = 0       # 繰り返した回数
    while n < 8:
        a.append(i % 2)   # 余り
        c.append(i)
        i = i //2           # 商
        n += 1

    # 要素を逆順にする
    # a.reverse()

    # 小数部を2進数に変換
    b = []      # かけた後の整数部を入れるリスト=2進の小数部
    d = []      # かけた後の小数部を入れるリスト
    n = 0       # 繰り返した回数
    while n < 8:
        temp = f * 2        # 小数部*2
        b.append(int(temp)) # かけた後の整数部
        d.append(round(f,9))
        f = temp - int(temp)
        n += 1
        if (n >= 10):
            break

    return a, b, c, d


# 2進-->10進変換 ('0','1','.' 以外の入力、整数部,小数部それぞれ8ケタを超える、場合はFalseを返す)
def bintodec(target2):
    # 入力をstrに変換
    target2 = str(target2)

    # 17ケタを超える、または、ピリオドが1つを超える、または、'0','1','.' 以外が入力されている場合は Falseを返す
    if len(target2) > 17 or target2.count('.') > 1 or len(target2) != (target2.count('0') + target2.count('1') + target2.count('.')):
        return False

    else:
        # 2進の各桁のリストを用意、入力文字をリストに1文字ずつ入れる
        e = []
        for x in range(len(target2)):
            e.append(target2[x])

        # '.'があるか判定、無ければリスト末尾に追加
        if '.' not in e:
            e.append('.')

        # 整数部、小数部が8桁を超えている場合は Falseを返す
        if e.index('.') > 8 or e.index('.') < len(e) - 9:
            return False

        else:
            # '.' 以外を数字にする
            for x in range(len(e)):
                if e[x] != '.':
                    e[x] = int(e[x])

            # '.' が e[8]になるまでリスト先頭に 0 を追加、追加後'.'を削除
            while e.index('.') != 8:
                e.insert(0, 0)
                if e.index('.') >= 8:
                    break
            e.remove('.')

            # 各ケタに重みをかけて合計を求める
            f = []
            g = 0.0
            for x in range(len(e)):
                f.append(e[x] * 2**(7-x))
                g += f[x]

            return e, f, g


