        qe.put([mid,0,2])
        total = int(filesize)
        findex = 0 
        with open(videopath,'rb') as fr:
            while fr.tell() < total:
                try:
                    fr.seek(fr.tell())
                    file_pd = fr.read(size)
                    nfile = nfname + str(findex)
                    desfile = os.path.join(newdir, nfile)
                    nf = open(desfile, 'wb')
                    nf.write(file_pd)
                    nf.close()
                    findex += 1
                    pers = float(findex*size) / total
                    pers = float('%.2f' % pers)
                    if pers > 1:
                        pers = 1
                    qe.put([mid,pers,-1])
                    print('分割进度:{}%'.format(pers))
                except IOError as e:
                    break
        qe.put([mid,100,3])

