from __future__ import absolute_import

import six
import string
import warnings

from collections import OrderedDict
from django.db import models
from django.utils import timezone
from django.utils.translation import ugettext_lazy as _

from sentry import eventtypes
from sentry.db.models import (
    BoundedBigIntegerField, BoundedIntegerField, Model, NodeField, sane_repr
)
from sentry.interfaces.base import get_interfaces
from sentry.utils.cache import memoize
from sentry.utils.canonical import CanonicalKeyDict, CanonicalKeyView
from sentry.utils.strings import truncatechars


class Event(Model):
    """
    An individual event.
    """
    __core__ = False

    group_id = BoundedBigIntegerField(blank=True, null=True)
    event_id = models.CharField(max_length=32, null=True, db_column="message_id")
    project_id = BoundedBigIntegerField(blank=True, null=True)
    message = models.TextField()
    platform = models.CharField(max_length=64, null=True)
    datetime = models.DateTimeField(default=timezone.now, db_index=True)
    time_spent = BoundedIntegerField(null=True)
    data = NodeField(
        blank=True,
        null=True,
        ref_func=lambda x: x.project_id or x.project.id,
        ref_version=2,
        wrapper=CanonicalKeyDict,
    )

    class Meta:
        app_label = 'sentry'
        db_table = 'sentry_message'
        verbose_name = _('message')
        verbose_name_plural = _('messages')
        unique_together = (('project_id', 'event_id'), )
        index_together = (('group_id', 'datetime'), )

    __repr__ = sane_repr('project_id', 'group_id')

    def __getstate__(self):
        state = Model.__getstate__(self)

        # do not pickle cached info.  We want to fetch this on demand
        # again.  In particular if we were to pickle interfaces we would
        # pickle a CanonicalKeyView which old sentry workers do not know
        # about
        state.pop('_project_cache', None)
        state.pop('_group_cache', None)
        state.pop('interfaces', None)

        return state

    # Implement a ForeignKey-like accessor for backwards compat
    def _set_group(self, group):
        self.group_id = group.id
        self._group_cache = group

    def _get_group(self):
        from sentry.models import Group
        if not hasattr(self, '_group_cache'):
            self._group_cache = Group.objects.get(id=self.group_id)
        return self._group_cache

    group = property(_get_group, _set_group)

    # Implement a ForeignKey-like accessor for backwards compat
    def _set_project(self, project):
        self.project_id = project.id
        self._project_cache = project

    def _get_project(self):
        from sentry.models import Project
        if not hasattr(self, '_project_cache'):
            self._project_cache = Project.objects.get(id=self.project_id)
        return self._project_cache

    project = property(_get_project, _set_project)

    def get_legacy_message(self):
        msg_interface = self.data.get('logentry', {
            'message': self.message,
        })
        return msg_interface.get('formatted', msg_interface['message'])

    def get_event_type(self):
        """
        Return the type of this event.

        See ``sentry.eventtypes``.
        """
        return self.data.get('type', 'default')

    def get_event_metadata(self):
        """
        Return the metadata of this event.

        See ``sentry.eventtypes``.
        """
        from sentry.event_manager import get_event_metadata_compat
        return get_event_metadata_compat(self.data, self.message)

    @property
    def title(self):
        et = eventtypes.get(self.get_event_type())(self.data)
        return et.to_string(self.get_event_metadata())

    def error(self):
        warnings.warn('Event.error is deprecated, use Event.title', DeprecationWarning)
        return self.title

    error.short_description = _('error')

    @property
    def message_short(self):
        warnings.warn('Event.message_short is deprecated, use Event.title', DeprecationWarning)
        return self.title

    @property
    def organization(self):
        return self.project.organization

    @property
    def version(self):
        return self.data.get('version', '5')

    @memoize
    def ip_address(self):
        user_data = self.data.get('user', self.data.get('user'))
        if user_data:
            value = user_data.get('ip_address')
            if value:
                return value

        http_data = self.data.get('request', self.data.get('http'))
        if http_data and 'env' in http_data:
            value = http_data['env'].get('REMOTE_ADDR')
            if value:
                return value

        return None

    def get_interfaces(self):
        return CanonicalKeyView(get_interfaces(self.data))

    @memoize
    def interfaces(self):
        return self.get_interfaces()

    def get_tags(self):
        try:
            return sorted((t, v) for t, v in self.data.get('tags') or ())
        except ValueError:
            # at one point Sentry allowed invalid tag sets such as (foo, bar)
            # vs ((tag, foo), (tag, bar))
            return []

    tags = property(get_tags)

    def get_tag(self, key):
        for t, v in (self.data.get('tags') or ()):
            if t == key:
                return v
        return None

    @property
    def dist(self):
        return self.get_tag('sentry:dist')

    def as_dict(self):
        # We use a OrderedDict to keep elements ordered for a potential JSON serializer
        data = OrderedDict()
        data['id'] = self.event_id
        data['project'] = self.project_id
        data['release'] = self.get_tag('sentry:release')
        data['dist'] = self.dist
        data['platform'] = self.platform
        data['culprit'] = self.group.culprit
        data['message'] = self.get_legacy_message()
        data['datetime'] = self.datetime
        data['time_spent'] = self.time_spent
        data['tags'] = self.get_tags()
        for k, v in sorted(six.iteritems(self.data)):
            if k == 'sdk':
                v = {v_k: v_v for v_k, v_v in six.iteritems(v) if v_k != 'client_ip'}
            data[k] = v
        return data

    @property
    def size(self):
        data_len = 0
        for value in six.itervalues(self.data):
            data_len += len(repr(value))
        return data_len

    # XXX(dcramer): compatibility with plugins
    def get_level_display(self):
        warnings.warn(
            'Event.get_level_display is deprecated. Use Event.tags instead.', DeprecationWarning
        )
        return self.group.get_level_display()

    @property
    def level(self):
        warnings.warn('Event.level is deprecated. Use Event.tags instead.', DeprecationWarning)
        return self.group.level

    @property
    def logger(self):
        warnings.warn('Event.logger is deprecated. Use Event.tags instead.', DeprecationWarning)
        return self.get_tag('logger')

    @property
    def site(self):
        warnings.warn('Event.site is deprecated. Use Event.tags instead.', DeprecationWarning)
        return self.get_tag('site')

    @property
    def server_name(self):
        warnings.warn('Event.server_name is deprecated. Use Event.tags instead.')
        return self.get_tag('server_name')

    @property
    def culprit(self):
        warnings.warn('Event.culprit is deprecated. Use Group.culprit instead.')
        return self.group.culprit

    @property
    def checksum(self):
        warnings.warn('Event.checksum is no longer used', DeprecationWarning)
        return ''

    @property
    def transaction(self):
        return self.get_tag('transaction')

    def get_email_subject(self):
        template = self.project.get_option('mail:subject_template')
        if template:
            template = EventSubjectTemplate(template)
        else:
            template = DEFAULT_SUBJECT_TEMPLATE
        return truncatechars(
            template.safe_substitute(
                EventSubjectTemplateData(self),
            ),
            128,
        ).encode('utf-8')

    def get_environment(self):
        from sentry.models import Environment

        if not hasattr(self, '_environment_cache'):
            self._environment_cache = Environment.objects.get(
                organization_id=self.project.organization_id,
                name=Environment.get_name_or_default(self.get_tag('environment')),
            )

        return self._environment_cache


class EventSubjectTemplate(string.Template):
    idpattern = r'(tag:)?[_a-z][_a-z0-9]*'


class EventSubjectTemplateData(object):
    tag_aliases = {
        'release': 'sentry:release',
        'dist': 'sentry:dist',
        'user': 'sentry:user',
    }

    def __init__(self, event):
        self.event = event

    def __getitem__(self, name):
        if name.startswith('tag:'):
            name = name[4:]
            value = self.event.get_tag(self.tag_aliases.get(name, name))
            if value is None:
                raise KeyError
            return six.text_type(value)
        elif name == 'project':
            return self.event.project.get_full_name()
        elif name == 'projectID':
            return self.event.project.slug
        elif name == 'shortID':
            return self.event.group.qualified_short_id
        elif name == 'orgID':
            return self.event.organization.slug
        elif name == 'title':
            return self.event.title
        raise KeyError


DEFAULT_SUBJECT_TEMPLATE = EventSubjectTemplate('$shortID - $title')

import xml.etree.ElementPath

import attr


@attr.s
class Element:
    tag = attr.ib()
    attrib = attr.ib(default=())
    children = attr.ib(default=attr.Factory(list))

    def append(self, element):
        self.children.append(element)

    def extend(self, elements):
        self.children.extend(elements)

    def insert(self, index, element):
        self.children.insert(index, element)

    def remove(self, element):
        self.children.remove(element)

    def findall(self, path):
        return list(self.iterfind(path))

    def find(self, path):
        return next(self.iterfind(path), None)

    def iterfind(self, path):
        queryable_element = QueryableElement(self)
        found = xml.etree.ElementPath.iterfind(queryable_element, path)
        for item in found:
            if isinstance(item, ListBackedElement):
                yield item.list
            elif isinstance(item, QueryableElement):
                yield item.element

    def iter(self, tag=None):
        return iterate_element(self, tag)

    def __iter__(self):
        return iter(self.children)

    def __getitem__(self, index):
        return self.children[index]

    def __setitem__(self, index, element):
        self.children[index] = element

    def __len__(self):
        return len(self.children)


@attr.s
class QueryableElement:
    element = attr.ib()

    @property
    def tag(self):
        return self.element.tag

    def iter(self, tag=None):
        return iterate_element(self, tag)

    def __iter__(self):
        for item in self.element:
            if isinstance(item, Element):
                yield QueryableElement(item)
            elif isinstance(item, list):
                yield ListBackedElement(item)


@attr.s
class ListBackedElement:
    list = attr.ib()

    @property
    def tag(self):
        return self.list[0]

    def iter(self, tag=None):
        if tag is None or self.tag == tag:
            yield self

    def __iter__(self):
        return iter(())


def iterate_element(element, tag):
    if tag is None or element.tag == tag:
        yield element
    for item in element:
        if hasattr(item, 'iter'):
            yield from item.iter(tag)
        elif tag is None:
            yield item

#!/usr/bin/env python3
"""
Реализация решателя головоломки какуро
"""

import sys
import re
import argparse
import slover


def main(args):
    '''
    Главная функция
    '''
    parser = argparse.ArgumentParser()
    parser.add_argument('-c', '--count', required=False, type=int,
                        help='This argument is a number of answers', default=1)
    parser.add_argument('-f', '--filename', required=False, type=str,
                        help='This argument is a file name, without '
                             'it you have to input data')
    parser.add_argument('-g', '--groups', nargs='+', required=False,
                        help='This argument are the coordinates of '
                             'cells whose values ​​are the same, '
                             'groups must be separated by "/", x and y '
                             'values must be separated by ",", '
                             'coordinate values must be separated by spaces')
    namespace = parser.parse_args(args)
    groups = []
    if namespace.groups is not None:
        groups.append([])
        cell = 0
        is_splited = False
        for item in namespace.groups:
            if item == ',':
                continue
            elif is_splited:
                groups[-1].append((cell, int(item)))
                is_splited = False
            elif re.search(re.compile(r'\d+,\d+'), item):
                coord = item.split(',')
                groups[-1].append((int(coord[0]), int(coord[1])))
            elif re.search(re.compile(r'\d+,'), item):
                cell = int(item[:-1])
                is_splited = True
            elif re.search(re.compile(r'\d+'), item):
                cell = int(item)
                is_splited = True
            elif item == '/':
                groups.append([])
    count = namespace.count
    strings = read_data(namespace.filename)
    try:
        board = Board(strings)
    except FormatException as err:
        print(err, file=sys.stderr)
        sys.exit(1)
    ans = list(map(str, slover.start(board, count, groups)))
    if ans:
        for answer in ans:
            print(answer)
            print()
        sys.exit(0)
    sys.exit(1)


def read_data(fname):
    """
    Функция, которая считывает входные данные
    """
    strings = []
    open_file = None
    if fname is not None:
        open_file = open(fname)
    else:
        open_file = sys.stdin
    with open_file as file:
        while True:
            line = file.readline()
            if not line.rstrip():
                break
            else:
                if line.strip() != "":
                    strings.append(line.strip())
    return strings


class FormatException(Exception):
    """
    Класс ошибки неправильного формата входных данных
    """
    def __init__(self, msg, line):
        super(FormatException, self).__init__(msg, line)
        self.type = msg
        self.line = line

    def __str__(self):
        return "{}: line {}".format(self.type, self.line)


class Cell:
    """
    Класс, описывающий клетку поля
    """
    def __init__(self, sum_vertical, sum_horizontal,
                 cur_sum_vertical, cur_sum_horizontal):
        self.cur_sum_horizontal = cur_sum_horizontal
        self.sum_horizontal = sum_horizontal
        self.sum_vertical = sum_vertical
        self.cur_sum_vertical = cur_sum_vertical
        self.value = 0

    def change_value(self, value, sum_horizontal, sum_vertical):
        """
        Функция, изменяющая значение клетки
        """
        self.cur_sum_horizontal = sum_horizontal + value - self.value
        self.cur_sum_vertical = sum_vertical + value - self.value
        self.value = value

    def __str__(self):
        return str(self.value)

class Board:
    """
    Класс, реализующий игровое поле
    """
    CELL_FORMAT = re.compile(r'(\d+|X)/(\d+|X)')

    def __init__(self, file):
        self.board = self.read(self.CELL_FORMAT, file)

    @staticmethod
    def read(cell_format, f_data):
        """
        Функция, считывающая данные в формат поля
        """
        def check_format(sum_board, is_vertical):
            for i in range(height):
                curr_sum = -1
                count = 0
                for j in range(width):
                    cell = sum_board[i][j]
                    if is_vertical:
                        cell = sum_board[j][i]
                    if cell != '0':
                        if curr_sum > (9 + 10 - count) * count / 2:
                            raise FormatException(
                                "Too large value of the sum", str(i + 1))
                        if cell != 'X':
                            curr_sum = int(cell)
                        if is_vertical:
                            sum_board[j][i] = 'X'
                        else:
                            sum_board[i][j] = 'X'
                    elif cell == '0':
                        count += 1
                        if curr_sum <= 0:
                            raise FormatException(
                                "Insufficient value of the sum", str(i + 1))
                        if is_vertical:
                            sum_board[j][i] = curr_sum
                        else:
                            sum_board[i][j] = curr_sum

        height = 0
        width = len(f_data[0].split(','))
        vertical_sum_board = []
        horizontal_sum_board = []
        for line in f_data:
            line_data = [i.strip() for i in line.split(',')
                         if (i.strip() != '')]
            horizontal_sum_board.append([])
            vertical_sum_board.append([])
            for cell in line_data:
                if cell in ('', '\n'):
                    continue
                found_cell = re.search(cell_format, cell)
                if found_cell is not None:
                    horizontal_sum_board[height].append(found_cell.group(1))
                    vertical_sum_board[height].append(found_cell.group(2))
                elif cell in ('X', '0'):
                    horizontal_sum_board[height].append(cell)
                    vertical_sum_board[height].append(cell)
                else:
                    raise FormatException("Wrong char", height + 1)
            height += 1

        check_format(horizontal_sum_board, False)
        check_format(vertical_sum_board, True)

        result = []
        for i in range(height):
            result.append([])
            for j in range(width):
                if vertical_sum_board[i][j] == 'X':
                    result[i].append('X')
                else:
                    result[i].append(Cell(vertical_sum_board[i][j],
                                          horizontal_sum_board[i][j], 0, 0))
        return result

    def __str__(self):
        lines = [' '.join(map(str, self.board[i]))
                 for i in range(len(self.board))]
        return '\n'.join(lines)


if __name__ == '__main__':
    main(sys.argv[1:])

