class IrGenerationErrorTests(unittest.TestCase):
    """Ensure illegal inputs raise proper exceptions."""

    def setUp(self):
        """Initialize the test schema once for all tests, and disable max diff limits."""
        self.maxDiff = None
        self.schema = get_schema()

    def test_no_traversing_from_optional_scope(self):
        # Until OrientDB fixes the limitation against traversing from an optional vertex,
        # attempting to do so will raise GraphQLCompilationError.
        # For details, see https://github.com/orientechnologies/orientdb/issues/6788
        graphql_input = '''{
            Animal {
                out_Animal_ParentOf @optional {
                    out_Animal_FedAt {
                        name @output(out_name: "name")
                    }
                }
            }
        }'''

        with self.assertRaises(GraphQLCompilationError):
            graphql_to_ir(self.schema, graphql_input)

    def test_repeated_field_name(self):
        repeated_property_field = '''{
            Animal {
                name @output(out_name: "name")
                name
            }
        }'''

        repeated_property_field_with_directives = '''{
            Animal {
                name @output(out_name: "name")
                name @filter(op_name: "=", value: ["$wanted"])
            }
        }'''

        repeated_vertex_field = '''{
            Animal {
                out_Animal_ParentOf {
                    name @output(out_name: "child_name")
                }
                out_Animal_ParentOf {
                    uuid @output(out_name: "child_uuid")
                }
            }
        }'''

        for graphql in (repeated_property_field,
                        repeated_property_field_with_directives,
                        repeated_vertex_field):
            with self.assertRaises(GraphQLCompilationError):
                graphql_to_ir(self.schema, graphql)

