@secure_service
def whichRulesOnEntity():
    response = Response()
    try:
        data = getDataRequest()
        client = repo.get_instance(INSTANCE)
        result = {'rules': [], 'tables': []}
        array = client.get_by_query(COLECTION_RULES, {'types': data['id']})

        for item in array:
            iresult = {'rule_name': item.get('name'), 'id': item.get('id')}
