#!/usr/bin/env python

import os, re, logging
from datetime import datetime, date

from bs4 import BeautifulSoup
from markdown import markdown

logger = logging.getLogger(__name__)

FILE_EXTENSION = 'mdtxt'
TIME_FMT = "%Y-%m-%d %H:%M:%S"

MD_EXTENSIONS = [
  'markdown.extensions.abbr',
  'markdown.extensions.tables',
  'markdown.extensions.codehilite',
  'mdx_math',
]
MD_EXT_CONFIGS = {
  'markdown.extensions.codehilite': { 'linenums': False, 'guess_lang': False},
  'mdx_math':   { 'enable_dollar_delimiter': True, },
}

def add_scrollable_to_pre(html_text):
    soup = BeautifulSoup(html_text, 'html.parser')
    pres = soup.select('.codehilite pre')
    for pre in pres:
        pre['class'] = 'pre-x-scrollable'
    return str(soup)

def add_bootstrap_table_style(html_text):
    soup = BeautifulSoup(html_text, 'html.parser')
    tables = soup.select('table')
    for table in tables:
        table['class'] = 'table table-striped'
    return str(soup)

def truncate_html(html, words):
    return str(BeautifulSoup(' '.join(html.split(' ')[:words]) + '...', "html.parser"))


class Post(dict):

    @property
    def rendered_content(self):
        self.render()
        return self['_rendered_content']

    @property
    def rendered_preview(self):
        self.render()
        return self['_rendered_preview']

    def render(self):
        if '_rendered_content' not in self or '_rendered_preview' not in self:
            rendered_content = markdown(self['content'], extensions=MD_EXTENSIONS, extension_configs=MD_EXT_CONFIGS)
            rendered_content = add_scrollable_to_pre(rendered_content)
            rendered_content = add_bootstrap_table_style(rendered_content)
            self['_rendered_content'] = rendered_content
            self['_rendered_preview'] = truncate_html(rendered_content, 50)

class Posts(object):


    def __init__(self, folder):
        self.folder = folder
        self.posts = []
        self.years = []
        self.months = []
        for file in os.listdir(folder):
            if file.endswith("." + FILE_EXTENSION):
                try:
                    self._add_post(file)
                except Exception as e:
                    logger.warn('Could not add the post %s for the following reason:', file)
                    logger.warn(str(e))
        self.update_collections()

    def update_collections(self):
        self.posts.sort(key=lambda post: post['creation_date'], reverse=True)
        del self.years[:]
        del self.months[:]
        for post in self.posts:
            year = date(post['creation_date'].year, 1, 1)
            month = date(post['creation_date'].year, post['creation_date'].month, 1)
            if year not in self.years:
                self.years.append(year)
            if month not in self.months:
                self.months.append(month)
        self.years.sort(reverse=True)
        self.months.sort(reverse=True)

    def _add_post(self, filename):
        filecontent = open(os.path.join(self.folder, filename), 'r').read()
        post = parse_post(filecontent)
        post['file'] = filename
        self.posts.append(post)

    def search_literally(self, search_phrase):
        search_phrase = search_phrase.lower()
        literal_results = []
        all_words_contained_results = []
        for post in self.posts:
            post_text = post['filecontent'].lower()
            if search_phrase in post_text:
                literal_results.append(post)
            elif all(word in post_text for word in search_phrase.split()):
                all_words_contained_results.append(post)
        return literal_results + all_words_contained_results

    @property
    def latest(self):
        newest_date = datetime(1000, 1, 1, 1, 1, 1)
        newest_post = None
        for post in self.posts:
            if post['creation_date'] > newest_date:
                newest_date = post['creation_date']
                newest_post = post
        return newest_post

    def keep_only(self, status_list):
        self.posts = [post for post in self.posts if post['status'] in status_list]
        self.update_collections()

    def keep_only_published(self):
        self.keep_only(['published'])

    def total(self):
        return len(self.posts)

def parse_post(text):
    post = Post()
    header, _, postcontent = text.partition("\n\n### Content\n\n")
    # title
    title = re.search(r"^# (?P<result>.*)$", header, re.MULTILINE)
    title = title.group('result')
    # categories
    categories = re.search(r"^\* Categories: (?P<result>.*)$", header, re.MULTILINE)
    if categories: categories = categories.group('result').split(', ')
    else: categories = []
    # tags
    tags = re.search(r"^\* Tags: (?P<result>.*)$", header, re.MULTILINE)
    if tags: tags = tags.group('result').split(', ')
    else: tags = []
    # creation_date
    creation_date = re.search(r"^\* Creation Date: (?P<result>.*)$", header, re.MULTILINE)
    creation_date = datetime.strptime(creation_date.group('result'), TIME_FMT)
    # modification_date
    modification_date = re.search(r"^\* Modification Date: (?P<result>.*)$", header, re.MULTILINE)
    if modification_date: modification_date = datetime.strptime(modification_date.group('result'), TIME_FMT)
    else: modification_date = creation_date
    # slug
    slug = re.search(r"^\* Slug: (?P<result>.*)$", header, re.MULTILINE)
    if slug: slug = slug.group('result')
    else: slug = None
    # status
    status = re.search(r"^\* Status: (?P<result>.*)$", header, re.MULTILINE)
    if status: status = status.group('result')
    else: status = 'draft'
    # address (from creation_date and )
    if status in ('published', 'private'): address = '/{:04d}/{:02d}/{}'.format(creation_date.year, creation_date.month, slug)
    else: address = None
    # done
    post['title'] = title
    post['categories'] = categories
    post['tags'] = tags
    post['creation_date'] = creation_date
    post['year'] = creation_date.year
    post['month'] = creation_date.month
    post['modification_date'] = modification_date
    post['status'] = status
    post['address'] = address
    post['slug'] = slug
    post['content'] = postcontent
    post['filecontent'] = text
    return post

if __name__ == "__main__":
    import argparse, pprint, random
    parser = argparse.ArgumentParser(description='Testing the posts module')
    parser.add_argument('local_blog_folder', help='Folder containing the blog posts')
    args = parser.parse_args()

    posts = Posts(args.local_blog_folder)

    print("This directory contains {} blog posts".format(posts.total()))

    posts.keep_only_published()
    print("The latest 10 published posts:")
    for post in posts.posts[-10:]:
        print("Title: {title}, slug: {slug}, status: {status}".format(**post))

from functools import wraps

from flask import Response, request, session
from flask_user import UserManager

from elasticsmapp.app.app import app, db
from elasticsmapp.app.models import User

user_manager = UserManager(app, db, User)


def custom_login(username, password, roles_accepted=None, users_accepted=None):
    user = user_manager.db_manager.find_user_by_username(username)

    if user is None:
        return False

    if not user_manager.verify_password(password, user.password):
        return False

    if roles_accepted or users_accepted:
        if roles_accepted:
            for role in user.roles:
                if role.name in roles_accepted:
                    return True

        if users_accepted:
            if user.username in users_accepted:
                return True

        return False

    return True


def authenticate():
    """Sends a 401 response that enables basic auth"""
    return Response(
        'Could not verify your access level for that URL.\n'
        'You have to login with proper credentials', 401,
        {'WWW-Authenticate': 'Basic realm="Login Required"'})


def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not custom_login(auth.username, auth.password, roles_accepted=['admin', 'user']):
            return authenticate()
        session['username'] = auth.username
        return f(*args, **kwargs)
    return decorated

from ..exceptions import HistoryFactoryNotFound
from ..utils import get_model_name
from .assessments.economic import EconomicAssessmentHistoryFactory
from .assessments.economic_impact import EconomicImpactAssessmentHistoryFactory
from .assessments.resolvability import ResolvabilityAssessmentHistoryFactory
from .assessments.strategic import StrategicAssessmentHistoryFactory
from .barriers import BarrierHistoryFactory
from .notes import NoteHistoryFactory
from .public_barrier_notes import PublicBarrierNoteHistoryFactory
from .public_barriers import PublicBarrierHistoryFactory
from .team_members import TeamMemberHistoryFactory
from .wto import WTOHistoryFactory


class HistoryItemFactory:
    """
    Proxy class for specific factory classes
    """

    class_lookup = {}
    history_factory_classes = (
        EconomicAssessmentHistoryFactory,
        EconomicImpactAssessmentHistoryFactory,
        BarrierHistoryFactory,
        NoteHistoryFactory,
        PublicBarrierHistoryFactory,
        PublicBarrierNoteHistoryFactory,
        ResolvabilityAssessmentHistoryFactory,
        StrategicAssessmentHistoryFactory,
        TeamMemberHistoryFactory,
        WTOHistoryFactory,
    )

    @classmethod
    def get_factory_class(cls, record):
        if not cls.class_lookup:
            cls.init_class_lookup()

        model_name = get_model_name(record)
        history_factory_class = cls.class_lookup.get(model_name)
        if not history_factory_class:
            raise HistoryFactoryNotFound
        return history_factory_class

    @classmethod
    def create(cls, field, new_record, old_record):
        factory_class = cls.get_factory_class(new_record)
        return factory_class.create(field, new_record, old_record)

    @classmethod
    def create_history_items(cls, new_record, old_record, fields=()):
        try:
            factory_class = cls.get_factory_class(new_record)
        except HistoryFactoryNotFound:
            return []
        return factory_class.create_history_items(new_record, old_record, fields)

    @classmethod
    def init_class_lookup(cls):
        """
        Initialise the class lookup so classes can be quickly fetched based on model
        """
        for factory_class in cls.history_factory_classes:
            cls.class_lookup[factory_class.get_model()] = factory_class

