def log(message):
    try:
        message = u"%s : %s \n" % (datetime.datetime.now().isoformat(), message)
        if settings.LOG_ENABLED:
            with io.open('/var/log/microimpuls/hydra.log', 'a', encoding='utf8') as f:
                f.write(message)
        else:
            print message
    except Exception as e:
        print "Can't write log: " + repr(e)


