# Mux Module name
def _MuxName(height, width):
    return f'Mux{height}x{width}'

def _MuxInterface(height, width):
    AW = In(Bits(width))
    if   height == 2:
        args = ['I0', AW, 
                'I1', AW]
        args += ['S', In(Bit)]
    elif height == 4:
        args = ['I0', AW, 
                'I1', AW,
                'I2', AW,
                'I3', AW]
        args += ['S', In(Bits(2))]
    elif height == 8:
        args = ['I0', AW, 
                'I1', AW,
                'I2', AW,
                'I3', AW,
                'I4', AW,
                'I5', AW,
                'I6', AW,
                'I7', AW]
        args += ['S', In(Bits(3))]
    elif height == 16:
        args = ['I0',  AW, 
                'I1',  AW,
                'I2',  AW,
                'I3',  AW,
                'I4',  AW,
                'I5',  AW,
                'I6',  AW,
                'I7',  AW,
                'I8',  AW, 
