from functools import wraps
from json import dumps
from typing import Any, Callable, Collection, Optional

from ..language.ast import Node, OperationType
from .visitor import visit, Visitor
from .block_string import print_block_string

__all__ = ["print_ast"]


Strings = Collection[str]


class PrintedNode:
    """A union type for all nodes that have been processed by the printer."""

    alias: str
    arguments: Strings
    block: bool
    default_value: str
    definitions: Strings
    description: str
    directives: str
    fields: Strings
    interfaces: Strings
    locations: Strings
    name: str
    operation: OperationType
    operation_types: Strings
    repeatable: bool
    selection_set: str
    selections: Strings
    type: str
    type_condition: str
    types: Strings
    value: str
    values: Strings
    variable: str
    variable_definitions: Strings


def print_ast(ast: Node) -> str:
    """Convert an AST into a string.

    The conversion is done using a set of reasonable formatting rules.
    """
    return visit(ast, PrintAstVisitor())


def add_description(method: Callable[..., str]) -> Callable:
    """Decorator adding the description to the output of a static visitor method."""

    @wraps(method)
    def wrapped(node: PrintedNode, *args: Any) -> str:
        return join((node.description, method(node, *args)), "\n")

    return wrapped


class PrintAstVisitor(Visitor):
    @staticmethod
    def leave_name(node: PrintedNode, *_args: Any) -> str:
        return node.value

    @staticmethod
    def leave_variable(node: PrintedNode, *_args: Any) -> str:
        return f"${node.name}"

    # Document

    @staticmethod
    def leave_document(node: PrintedNode, *_args: Any) -> str:
        return join(node.definitions, "\n\n") + "\n"

    @staticmethod
    def leave_operation_definition(node: PrintedNode, *_args: Any) -> str:
        name, op, selection_set = node.name, node.operation, node.selection_set
        var_defs = wrap("(", join(node.variable_definitions, ", "), ")")
        directives = join(node.directives, " ")
        # Anonymous queries with no directives or variable definitions can use the
        # query short form.
        return (
            join((op.value, join((name, var_defs)), directives, selection_set), " ")
            if (name or directives or var_defs or op != OperationType.QUERY)
            else selection_set
        )

    @staticmethod
    def leave_variable_definition(node: PrintedNode, *_args: Any) -> str:
        return (
            f"{node.variable}: {node.type}"
            f"{wrap(' = ', node.default_value)}"
            f"{wrap(' ', join(node.directives, ' '))}"
        )

    @staticmethod
    def leave_selection_set(node: PrintedNode, *_args: Any) -> str:
        return block(node.selections)

    @staticmethod
    def leave_field(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                wrap("", node.alias, ": ")
                + node.name
                + wrap("(", join(node.arguments, ", "), ")"),
                join(node.directives, " "),
                node.selection_set,
            ),
            " ",
        )

    @staticmethod
    def leave_argument(node: PrintedNode, *_args: Any) -> str:
        return f"{node.name}: {node.value}"

    # Fragments

    @staticmethod
    def leave_fragment_spread(node: PrintedNode, *_args: Any) -> str:
        return f"...{node.name}{wrap(' ', join(node.directives, ' '))}"

    @staticmethod
    def leave_inline_fragment(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                "...",
                wrap("on ", node.type_condition),
                join(node.directives, " "),
                node.selection_set,
            ),
            " ",
        )

    @staticmethod
    def leave_fragment_definition(node: PrintedNode, *_args: Any) -> str:
        # Note: fragment variable definitions are experimental and may be changed or
        # removed in the future.
        return (
            f"fragment {node.name}"
            f"{wrap('(', join(node.variable_definitions, ', '), ')')}"
            f" on {node.type_condition}"
            f" {wrap('', join(node.directives, ' '), ' ')}"
            f"{node.selection_set}"
        )

    # Value

    @staticmethod
    def leave_int_value(node: PrintedNode, *_args: Any) -> str:
        return node.value

    @staticmethod
    def leave_float_value(node: PrintedNode, *_args: Any) -> str:
        return node.value

    @staticmethod
    def leave_string_value(node: PrintedNode, key: str, *_args: Any) -> str:
        if node.block:
            return print_block_string(node.value, "" if key == "description" else "  ")
        return dumps(node.value)

    @staticmethod
    def leave_boolean_value(node: PrintedNode, *_args: Any) -> str:
        return "true" if node.value else "false"

    @staticmethod
    def leave_null_value(_node: PrintedNode, *_args: Any) -> str:
        return "null"

    @staticmethod
    def leave_enum_value(node: PrintedNode, *_args: Any) -> str:
        return node.value

    @staticmethod
    def leave_list_value(node: PrintedNode, *_args: Any) -> str:
        return f"[{join(node.values, ', ')}]"

    @staticmethod
    def leave_object_value(node: PrintedNode, *_args: Any) -> str:
        return f"{{{join(node.fields, ', ')}}}"

    @staticmethod
    def leave_object_field(node: PrintedNode, *_args: Any) -> str:
        return f"{node.name}: {node.value}"

    # Directive

    @staticmethod
    def leave_directive(node: PrintedNode, *_args: Any) -> str:
        return f"@{node.name}{wrap('(', join(node.arguments, ', '), ')')}"

    # Type

    @staticmethod
    def leave_named_type(node: PrintedNode, *_args: Any) -> str:
        return node.name

    @staticmethod
    def leave_list_type(node: PrintedNode, *_args: Any) -> str:
        return f"[{node.type}]"

    @staticmethod
    def leave_non_null_type(node: PrintedNode, *_args: Any) -> str:
        return f"{node.type}!"

    # Type System Definitions

    @staticmethod
    @add_description
    def leave_schema_definition(node: PrintedNode, *_args: Any) -> str:
        return join(
            ("schema", join(node.directives, " "), block(node.operation_types)), " "
        )

    @staticmethod
    def leave_operation_type_definition(node: PrintedNode, *_args: Any) -> str:
        return f"{node.operation.value}: {node.type}"

    @staticmethod
    @add_description
    def leave_scalar_type_definition(node: PrintedNode, *_args: Any) -> str:
        return join(("scalar", node.name, join(node.directives, " ")), " ")

    @staticmethod
    @add_description
    def leave_object_type_definition(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                "type",
                node.name,
                wrap("implements ", join(node.interfaces, " & ")),
                join(node.directives, " "),
                block(node.fields),
            ),
            " ",
        )

    @staticmethod
    @add_description
    def leave_field_definition(node: PrintedNode, *_args: Any) -> str:
        args = node.arguments
        args = (
            wrap("(\n", indent(join(args, "\n")), "\n)")
            if has_multiline_items(args)
            else wrap("(", join(args, ", "), ")")
        )
        directives = wrap(" ", join(node.directives, " "))
        return f"{node.name}{args}: {node.type}{directives}"

    @staticmethod
    @add_description
    def leave_input_value_definition(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                f"{node.name}: {node.type}",
                wrap("= ", node.default_value),
                join(node.directives, " "),
            ),
            " ",
        )

    @staticmethod
    @add_description
    def leave_interface_type_definition(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                "interface",
                node.name,
                wrap("implements ", join(node.interfaces, " & ")),
                join(node.directives, " "),
                block(node.fields),
            ),
            " ",
        )

    @staticmethod
    @add_description
    def leave_union_type_definition(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                "union",
                node.name,
                join(node.directives, " "),
                "= " + join(node.types, " | ") if node.types else "",
            ),
            " ",
        )

    @staticmethod
    @add_description
    def leave_enum_type_definition(node: PrintedNode, *_args: Any) -> str:
        return join(
            ("enum", node.name, join(node.directives, " "), block(node.values)), " "
        )

    @staticmethod
    @add_description
    def leave_enum_value_definition(node: PrintedNode, *_args: Any) -> str:
        return join((node.name, join(node.directives, " ")), " ")

    @staticmethod
    @add_description
    def leave_input_object_type_definition(node: PrintedNode, *_args: Any) -> str:
        return join(
            ("input", node.name, join(node.directives, " "), block(node.fields)), " "
        )

    @staticmethod
    @add_description
    def leave_directive_definition(node: PrintedNode, *_args: Any) -> str:
        args = node.arguments
        args = (
            wrap("(\n", indent(join(args, "\n")), "\n)")
            if has_multiline_items(args)
            else wrap("(", join(args, ", "), ")")
        )
        repeatable = " repeatable" if node.repeatable else ""
        locations = join(node.locations, " | ")
        return f"directive @{node.name}{args}{repeatable} on {locations}"

    @staticmethod
    def leave_schema_extension(node: PrintedNode, *_args: Any) -> str:
        return join(
            ("extend schema", join(node.directives, " "), block(node.operation_types)),
            " ",
        )

    @staticmethod
    def leave_scalar_type_extension(node: PrintedNode, *_args: Any) -> str:
        return join(("extend scalar", node.name, join(node.directives, " ")), " ")

    @staticmethod
    def leave_object_type_extension(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                "extend type",
                node.name,
                wrap("implements ", join(node.interfaces, " & ")),
                join(node.directives, " "),
                block(node.fields),
            ),
            " ",
        )

    @staticmethod
    def leave_interface_type_extension(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                "extend interface",
                node.name,
                wrap("implements ", join(node.interfaces, " & ")),
                join(node.directives, " "),
                block(node.fields),
            ),
            " ",
        )

    @staticmethod
    def leave_union_type_extension(node: PrintedNode, *_args: Any) -> str:
        return join(
            (
                "extend union",
                node.name,
                join(node.directives, " "),
                "= " + join(node.types, " | ") if node.types else "",
            ),
            " ",
        )

    @staticmethod
    def leave_enum_type_extension(node: PrintedNode, *_args: Any) -> str:
        return join(
            ("extend enum", node.name, join(node.directives, " "), block(node.values)),
            " ",
        )

    @staticmethod
    def leave_input_object_type_extension(node: PrintedNode, *_args: Any) -> str:
        return join(
            ("extend input", node.name, join(node.directives, " "), block(node.fields)),
            " ",
        )


def join(strings: Optional[Strings], separator: str = "") -> str:
    """Join strings in a given collection.

    Return an empty string if it is None or empty, otherwise join all items together
    separated by separator if provided.
    """
    return separator.join(s for s in strings if s) if strings else ""


def block(strings: Optional[Strings]) -> str:
    """Return strings inside a block.

    Given a collection of strings, return a string with each item on its own line,
    wrapped in an indented "{ }" block.
    """
    return wrap("{\n", indent(join(strings, "\n")), "\n}")


def wrap(start: str, string: Optional[str], end: str = "") -> str:
    """Wrap string inside other strings at start and end.

    If the string is not None or empty, then wrap with start and end, otherwise return
    an empty string.
    """
    return f"{start}{string}{end}" if string else ""


def indent(string: str) -> str:
    """Indent string with two spaces.

    If the string is not None or empty, add two spaces at the beginning of every line
    inside the string.
    """
    return wrap("  ", string.replace("\n", "\n  "))


def is_multiline(string: str) -> bool:
    """Check whether a string consists of multiple lines."""
    return "\n" in string


def has_multiline_items(strings: Optional[Strings]) -> bool:
    """Check whether one of the items in the list has multiple lines."""
    return any(is_multiline(item) for item in strings) if strings else False

from copy import deepcopy
import numpy as np
from collections import Counter, namedtuple


class Node:
    def evaluate(self, *args, **kwargs):
        raise NotImplementedError()


class InputNode(Node):
    def __init__(self, name):
        self._name = name

    def evaluate(self, *args, **kwargs):
        pass

    def get_name(self):
        return self._name


class NotNode(Node):
    def evaluate(self, x, *args, **kwargs):
        return not x


class AndNode(Node):
    def evaluate(self, x, y, *args, **kwargs):
        return x and y


class OrNode(Node):
    def evaluate(self, x, y, *args, **kwargs):
        return x or y


class LogicalCircuit:
    def __init__(self, nodes, inputs, terminal_node=None, eliminate_or_nodes=False):
        self._nodes = nodes
        self._terminal_node = terminal_node or (len(nodes) - 1)
        self._inputs = inputs
        if eliminate_or_nodes:
            self._eliminate_or_nodes()

    def get_nodes(self):
        return self._nodes

    def get_inputs(self):
        return self._inputs

    def get_terminal_node(self):
        return self._terminal_node

    def copy(self):
        return LogicalCircuit(*map(deepcopy, [self._nodes, self._inputs, self._terminal_node]))

    def get_topological_order(self):
        def traverse_dfs(node, visited, nodes_black):
            visited[node] = True
            for node_input in self._inputs[node]:
                if not visited[node_input]:
                    traverse_dfs(node_input, visited, nodes_black)
            nodes_black.append(node)

        topological_order = []
        is_visited = [False] * len(self._nodes)
        for node_idx in range(len(self._nodes)):
            if not is_visited[node_idx]:
                traverse_dfs(node_idx, is_visited, topological_order)
        return topological_order

    def _add_node(self, node, inputs=None):
        inputs = inputs or []
        self._nodes.append(node)
        self._inputs.append(inputs)
        return len(self._nodes) - 1

    def _eliminate_or_nodes(self):
        node_indices = list(range(len(self._nodes)))
        for node_idx in node_indices:
            node = self._nodes[node_idx]
            if isinstance(node, OrNode):
                inputs = self._inputs[node_idx]
                node_not_x_idx = self._add_node(NotNode(), [inputs[0]])
                node_not_y_idx = self._add_node(NotNode(), [inputs[1]])
                node_and_idx = self._add_node(AndNode(), [node_not_x_idx, node_not_y_idx])
                self._nodes[node_idx] = NotNode()
                self._inputs[node_idx] = [node_and_idx]
        return self


class Permutation:
    @staticmethod
    def identity(size):
        return Permutation(np.fromiter(range(size), dtype=np.int))

    def __init__(self, permutation):
        if len(Counter(permutation)) < permutation.shape[0]:
            raise ValueError('Elements of the permutation are not unique')
        self._p = np.array(permutation)

    def __mul__(self, right):
        result = np.zeros(self._p.shape, dtype=np.int)
        for x in range(self._p.shape[0]):
            result[x] = self[right[x]]
        return Permutation(result)

    def __call__(self, elements, *args, **kwargs):
        result = np.zeros(elements.shape, dtype=elements.dtype)
        for idx, element in enumerate(elements):
            result[self._p[idx]] = element
        return result

    def __eq__(self, other):
        return np.all(self._p == other.get())

    def __getitem__(self, item):
        return self._p[item]

    def __len__(self):
        return len(self._p)

    def is_identity(self):
        return self.identity(len(self._p)) == self

    def get(self):
        return self._p

    def invert(self):
        result = np.zeros(self._p.shape, dtype=self._p.dtype)
        for x in range(self._p.shape[0]):
            result[self._p[x]] = x
        return Permutation(result)

    def calc_conjugate(self, other):
        result = np.zeros(self._p.shape, dtype=self._p.dtype)
        x_from, x_to = 0, 0
        for i in range(self._p.shape[0]):
            if i > 0:
                x_from, x_to = self._p[x_from], other[x_to]
            result[x_from] = x_to

        assert other == Permutation(result) * self * Permutation(result).invert()
        return Permutation(result)


class BranchingProgram:
    @staticmethod
    def build_from_permuting_branching_program(pbp_program, remove_unreachable=True, reduce_outputs=True):
        sigma = pbp_program.get_sigma()
        node_input = next(node for node in range(len(sigma)) if node != sigma[node])
        node_count = ((len(pbp_program.instructions) + 1) * len(sigma))
        graph = [None] * node_count
        node_labels = [None if node < node_count - len(sigma) else True for node in range(node_count)]
        node_output_false = len(pbp_program.instructions) * len(sigma) + node_input
        node_labels[node_output_false] = False
        for layer_idx, (var, perm_false, perm_true) in enumerate(pbp_program.instructions[::-1]):
            for node_idx_in_layer in range(len(sigma)):
                node = layer_idx * len(sigma) + node_idx_in_layer
                graph[node] = {
                    False: (layer_idx + 1) * len(sigma) + perm_false[node_idx_in_layer],
                    True: (layer_idx + 1) * len(sigma) + perm_true[node_idx_in_layer]
                }
                node_labels[node] = var
        graph[-len(sigma):] = [{False: None, True: None} for _ in range(len(sigma))]
        return BranchingProgram(graph, node_labels, node_input, remove_unreachable, reduce_outputs)

    def __init__(self, graph, labels, node_input=0, remove_unreachable=True, reduce_outputs=True):
        self._graph = graph
        self._node_labels = labels
        self._node_input = node_input
        if remove_unreachable:
            self._remove_unreachable()
        if reduce_outputs:
            self._reduce_outputs()

    def _remove_unreachable(self):
        def traverse_dfs(node, visited):
            visited[node] = True
            for node_target in self._graph[node].values():
                if node_target is not None and not visited[node_target]:
                    traverse_dfs(node_target, visited)

        is_reachable = [False] * len(self._graph)
        traverse_dfs(self._node_input, is_reachable)
        nodes_reachable = [node for node in range(len(self._graph)) if is_reachable[node]]
        node_renumbering = {node: node_idx_new for node_idx_new, node in enumerate(nodes_reachable)}
        graph = [{
            False: node_renumbering[self._graph[node][False]] if self._graph[node][False] is not None else None,
            True: node_renumbering[self._graph[node][True]] if self._graph[node][True] is not None else None,
        } for node in nodes_reachable]
        node_labels = [self._node_labels[node] for node in nodes_reachable]
        self._graph = graph
        self._node_labels = node_labels
        self._node_input = 0

    def _reduce_outputs(self):
        outputs = {node for node in range(len(self._graph)) if isinstance(self._node_labels[node], bool)}
        output_false = next(output for output in outputs if not self._node_labels[output])
        outputs_true = outputs - {output_false}
        output_false_new = min(outputs)
        output_true_new = output_false_new + 1
        self._graph = self._graph[:output_true_new + 1]
        for node in range(len(self._graph)):
            for edge_type in [False, True]:
                if self._graph[node][edge_type] in outputs_true:
                    self._graph[node][edge_type] = output_true_new
                elif self._graph[node][edge_type] == output_false:
                    self._graph[node][edge_type] = output_false_new
        self._node_labels = self._node_labels[:len(self._graph)]
        self._node_labels[output_false_new], self._node_labels[output_true_new] = False, True

    def get_labels(self):
        return self._node_labels

    def get_graph(self):
        return self._graph

    def get_input(self):
        return self._node_input

    def evaluate(self, var_values):
        node = self._node_input
        while not isinstance(self._node_labels[node], bool):
            node = self._graph[node][var_values[self._node_labels[node]]]
        return self._node_labels[node]


class PermutingBranchingProgram:
    Instruction = namedtuple('Instruction', ['var', 'perm_false', 'perm_true'])

    @staticmethod
    def build_from_circuit(circuit, sigma=None):
        node_to_program = {}
        sigma = sigma or Permutation(np.array([1, 2, 3, 4, 0]))
        topological_order = circuit.get_topological_order()
        for node_idx in topological_order:
            node = circuit.get_nodes()[node_idx]
            if isinstance(node, InputNode):
                node_to_program[node_idx] = PermutingBranchingProgram([
                    PermutingBranchingProgram.Instruction(node.get_name(),
                                                          Permutation.identity(5),
                                                          sigma)
                ], sigma)
            elif isinstance(node, NotNode):
                node_input = circuit.get_inputs()[node_idx][0]
                node_to_program[node_idx] = node_to_program[node_input].invert()
            elif isinstance(node, AndNode):
                node_inputs = circuit.get_inputs()[node_idx]
                node_to_program[node_idx] = node_to_program[node_inputs[0]].intersect(node_to_program[node_inputs[1]])
            else:
                raise ValueError('Unsupported node type')
        return node_to_program[circuit.get_terminal_node()]

    def __init__(self, instructions, final_permutation):
        self.instructions = instructions
        self._sigma = final_permutation

    def get_sigma(self):
        return self._sigma

    def change_sigma(self, sigma_new):
        instructions = [None] * len(self.instructions)
        if len(instructions) == 1:
            if self.instructions[0].perm_false == Permutation.identity(len(self.instructions[0].perm_false.get())):
                instructions[0] = self.Instruction(self.instructions[0].var,
                                                   self.instructions[0].perm_false,
                                                   sigma_new)
            else:
                instructions[0] = self.Instruction(self.instructions[0].var,
                                                   sigma_new,
                                                   self.instructions[0].perm_true)
        else:
            gamma = self._sigma.calc_conjugate(sigma_new)
            gamma_inverted = gamma.invert()
            instructions[0] = self.Instruction(self.instructions[0].var,
                                               gamma * self.instructions[0].perm_false,
                                               gamma * self.instructions[0].perm_true)
            instructions[1:-1] = self.instructions[1:-1]
            instructions[-1] = self.Instruction(self.instructions[-1].var,
                                                self.instructions[-1].perm_false * gamma_inverted,
                                                self.instructions[-1].perm_true * gamma_inverted)
        return PermutingBranchingProgram(instructions, sigma_new)

    def invert(self):
        instructions = self.change_sigma(self._sigma.invert()).instructions
        instructions[-1] = self.Instruction(instructions[-1].var,
                                            instructions[-1].perm_false * self._sigma,
                                            instructions[-1].perm_true * self._sigma)
        return PermutingBranchingProgram(instructions, self._sigma)

    def intersect(self, other, preserve_sigma=True, non_commuting_sigma=None):
        sigma_inverted = self._sigma.invert()
        other_sigma_inverted = other.get_sigma().invert()
        if (self._sigma * other.get_sigma() * sigma_inverted * other_sigma_inverted).is_identity():
            non_commuting_sigma = non_commuting_sigma or Permutation(np.array([2, 4, 1, 0, 3]))
            other_sigma_inverted = non_commuting_sigma.invert()
            if (self._sigma * non_commuting_sigma * sigma_inverted * other_sigma_inverted).is_identity():
                raise ValueError('Commuting sigma provided')
            other = other.change_sigma(non_commuting_sigma)
        instructions = [None] * (2 * (len(self.instructions) + len(other.instructions)))
        left, right = 0, len(self.instructions)
        instructions[left:right] = self.instructions
        left, right = right, right + len(other.instructions)
        instructions[left:right] = other.instructions
        left, right = right, right + len(self.instructions)
        instructions[left:right] = self.change_sigma(sigma_inverted).instructions
        left, right = right, right + len(other.instructions)
        instructions[left:right] = other.change_sigma(other_sigma_inverted).instructions
        result = PermutingBranchingProgram(instructions,
                                           self._sigma * other.get_sigma() * sigma_inverted * other_sigma_inverted)
        if preserve_sigma:
            result = result.change_sigma(self._sigma)
        return result


def parse_node(node_str):
    node_description = node_str.split()
    inputs_start_idx = 1
    if node_description[0] == 'VAR':
        node = InputNode(node_description[1])
        inputs_start_idx = 2
    elif node_description[0] == 'OR':
        node = OrNode()
    elif node_description[0] == 'AND':
        node = AndNode()
    elif node_description[0] == 'NOT':
        node = NotNode()
    else:
        raise ValueError('Wrong node type in input')
    inputs = list(map(int, node_description[inputs_start_idx:]))
    return node, inputs


def solve(nodes, node_inputs):
    circuit = LogicalCircuit(nodes, node_inputs, len(nodes) - 1, eliminate_or_nodes=True)
    permuting_program = PermutingBranchingProgram.build_from_circuit(circuit)
    return BranchingProgram.build_from_permuting_branching_program(permuting_program)


if __name__ == '__main__':
    node_count = int(input())
    node_inputs = [None] * node_count
    nodes = [None] * node_count
    for idx in range(node_count):
        nodes[idx], node_inputs[idx] = parse_node(input())
    branching_program = solve(nodes, node_inputs)
    graph, labels = branching_program.get_graph(), branching_program.get_labels()
    for node in range(len(graph)):
        label = labels[node]
        if isinstance(label, bool):
            label = str(label).upper()
            print(f'{label}')
        else:
            print(f'{label} {graph[node][False]} {graph[node][True]}')

from django.contrib.auth import authenticate, login, logout
from django.contrib.auth.decorators import login_required
from django.db import IntegrityError
from django.http import HttpResponse, HttpResponseRedirect
from django.shortcuts import render
from django.urls import reverse

from .models import User, Category, Listing, Bid, Comment

def index(request):
    return render(request, "auctions/index.html", {
        "title": "Active Listings",
        "listings": Listing.objects.exclude(status=False).all()
    })

def login_view(request):
    if request.method == "POST":

        # Attempt to sign user in
        username = request.POST["username"]
        password = request.POST["password"]
        user = authenticate(request, username=username, password=password)

        # Check if authentication successful
        if user is not None:
            login(request, user)
            return HttpResponseRedirect(reverse("index"))
        else:
            return render(request, "auctions/login.html", {
                "message": "Invalid username and/or password."
            })
    else:
        return render(request, "auctions/login.html")


def logout_view(request):
    logout(request)
    return HttpResponseRedirect(reverse("index"))


def register(request):
    if request.method == "POST":
        username = request.POST["username"]
        email = request.POST["email"]

        # Ensure password matches confirmation
        password = request.POST["password"]
        confirmation = request.POST["confirmation"]
        if password != confirmation:
            return render(request, "auctions/register.html", {
                "message": "Passwords must match."
            })

        # Attempt to create new user
        try:
            user = User.objects.create_user(username, email, password)
            user.save()
        except IntegrityError:
            return render(request, "auctions/register.html", {
                "message": "Username already taken."
            })
        login(request, user)
        return HttpResponseRedirect(reverse("index"))
    else:
        return render(request, "auctions/register.html")

