from . import logging, renderer
import io
import itertools
import os
import requests
import stat
import tarfile

__all__ = ['Builder']

LOG = logging.getLogger(__name__)


class Builder:
    def __init__(self, config, *, validators=False):
        self.config = config
        self.validators = validators
        self._file_cache = None

    @property
    def file_cache(self):
        if not self._file_cache:
            self._build_file_cache()
        return self._file_cache

    def _build_file_cache(self):
        self._file_cache = {}
        for file_spec in self._file_specs:
            path = file_spec['path']
            if 'content' in file_spec:
                data = file_spec['content']
            elif 'tar_url' in file_spec:
                data = _fetch_tar_content(
                    url=file_spec['tar_url'], path=file_spec['tar_path'])
            self._file_cache[path] = {
                'path': path,
                'data': data,
                'mode': file_spec['mode'],
            }

    @property
    def _file_specs(self):
        return itertools.chain(
            self.config.get_path('HostSystem:files', []),
            self.config.get_path('Genesis:files', []))

    def build_all(self, *, output_dir):
        self.build_genesis(output_dir=output_dir)
        for node_document in self.config.iterate(
                schema='promenade/KubernetesNode/v1'):
            self.build_node(node_document, output_dir=output_dir)

        if self.validators:
            validate_script = renderer.render_template(
                self.config, template='scripts/validate-cluster.sh')
            _write_script(output_dir, 'validate-cluster.sh', validate_script)

    def build_genesis(self, *, output_dir):
        LOG.info('Building genesis script')
        sub_config = self.config.extract_genesis_config()
        tarball = renderer.build_tarball_from_roles(
            config=sub_config,
            roles=['common', 'genesis'],
            file_specs=self.file_cache.values())

        script = renderer.render_template(
            sub_config,
            template='scripts/genesis.sh',
            context={
                'tarball': tarball
            })

        _write_script(output_dir, 'genesis.sh', script)

        if self.validators:
            validate_script = renderer.render_template(
                sub_config, template='scripts/validate-genesis.sh')
            _write_script(output_dir, 'validate-genesis.sh', validate_script)

    def build_node(self, node_document, *, output_dir):
        node_name = node_document['metadata']['name']
        LOG.info('Building script for node %s', node_name)
        script = self.build_node_script(node_name)

        _write_script(output_dir, _join_name(node_name), script)

        if self.validators:
            validate_script = self._build_node_validate_script(node_name)
            _write_script(output_dir, 'validate-%s.sh' % node_name,
                          validate_script)

    def build_node_script(self, node_name):
        sub_config = self.config.extract_node_config(node_name)
        file_spec_paths = [
            f['path'] for f in self.config.get_path('HostSystem:files', [])
        ]
        file_specs = [self.file_cache[p] for p in file_spec_paths]
        tarball = renderer.build_tarball_from_roles(
            config=sub_config, roles=['common', 'join'], file_specs=file_specs)

        return renderer.render_template(
            sub_config,
            template='scripts/join.sh',
            context={
                'tarball': tarball
            })

    def _build_node_validate_script(self, node_name):
        sub_config = self.config.extract_node_config(node_name)
        return renderer.render_template(
            sub_config, template='scripts/validate-join.sh')


def _fetch_tar_content(*, url, path):
    LOG.debug('Fetching url=%s (tar path=%s)', url, path)
    response = requests.get(url)
    response.raise_for_status()
    LOG.debug('Finished downloading url=%s (tar path=%s)', url, path)
    f = io.BytesIO(response.content)
    tf = tarfile.open(fileobj=f, mode='r')
    buf_reader = tf.extractfile(path)
    return buf_reader.read()


def _join_name(node_name):
    return 'join-%s.sh' % node_name


def _write_script(output_dir, name, script):
    path = os.path.join(output_dir, name)
    with open(path, 'w') as f:
        f.write(script)

    os.chmod(
        path,
        os.stat(path).st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)

import asyncio
import pytest
import random

from unittest import mock

from aiocache import cached, cached_stampede, multi_cached


async def return_dict(keys=None):
    ret = {}
    for value, key in enumerate(keys or [pytest.KEY, pytest.KEY_1]):
        ret[key] = str(value)
    return ret


async def stub(*args, key=None, seconds=0, **kwargs):
    await asyncio.sleep(seconds)
    if key:
        return str(key)
    return str(random.randint(1, 50))


class TestCached:
    @pytest.fixture(autouse=True)
    def default_cache(self, mocker, cache):
        mocker.patch("aiocache.decorators._get_cache", return_value=cache)

    @pytest.mark.asyncio
    async def test_cached_ttl(self, cache):
        @cached(ttl=1, key=pytest.KEY)
        async def fn():
            return str(random.randint(1, 50))

        resp1 = await fn()
        resp2 = await fn()

        assert await cache.get(pytest.KEY) == resp1 == resp2
        await asyncio.sleep(1)
        assert await cache.get(pytest.KEY) is None

    @pytest.mark.asyncio
    async def test_cached_key_builder(self, cache):
        def build_key(f, self, a, b):
            return "{}_{}_{}_{}".format(self, f.__name__, a, b)

        @cached(key_builder=build_key)
        async def fn(self, a, b=2):
            return "1"

        await fn("self", 1, 3)
        assert await cache.exists(build_key(fn, "self", 1, 3)) is True


class TestCachedStampede:
    @pytest.fixture(autouse=True)
    def default_cache(self, mocker, cache):
        mocker.patch("aiocache.decorators._get_cache", return_value=cache)

    @pytest.mark.asyncio
    async def test_cached_stampede(self, mocker, cache):
        mocker.spy(cache, "get")
        mocker.spy(cache, "set")
        decorator = cached_stampede(ttl=10, lease=2)

        await asyncio.gather(decorator(stub)(0.5), decorator(stub)(0.5))

        cache.get.assert_called_with("acceptance.test_decoratorsstub(0.5,)[]")
        assert cache.get.call_count == 4
        cache.set.assert_called_with("acceptance.test_decoratorsstub(0.5,)[]", mock.ANY, ttl=10)
        assert cache.set.call_count == 1

    @pytest.mark.asyncio
    async def test_locking_dogpile_lease_expiration(self, mocker, cache):
        mocker.spy(cache, "get")
        mocker.spy(cache, "set")
        decorator = cached_stampede(ttl=10, lease=3)

        await asyncio.gather(
            decorator(stub)(1, seconds=1),
            decorator(stub)(1, seconds=2),
            decorator(stub)(1, seconds=3),
        )

        assert cache.get.call_count == 6
        assert cache.set.call_count == 3

    @pytest.mark.asyncio
    async def test_locking_dogpile_task_cancellation(self, mocker, cache):
        @cached_stampede()
        async def cancel_task():
            raise asyncio.CancelledError()

        with pytest.raises(asyncio.CancelledError):
            await cancel_task()


class TestMultiCachedDecorator:
    @pytest.fixture(autouse=True)
    def default_cache(self, mocker, cache):
        mocker.patch("aiocache.decorators._get_cache", return_value=cache)

    @pytest.mark.asyncio
    async def test_multi_cached(self, cache):
        multi_cached_decorator = multi_cached("keys")

        default_keys = {pytest.KEY, pytest.KEY_1}
        await multi_cached_decorator(return_dict)(keys=default_keys)

        for key in default_keys:
            assert await cache.get(key) is not None

    @pytest.mark.asyncio
    async def test_keys_without_kwarg(self, cache):
        @multi_cached("keys")
        async def fn(keys):
            return {pytest.KEY: 1}

        await fn([pytest.KEY])
        assert await cache.exists(pytest.KEY) is True

    @pytest.mark.asyncio
    async def test_multi_cached_key_builder(self, cache):
        def build_key(key, self, keys, market="ES"):
            return "{}_{}".format(key, market)

        @multi_cached(keys_from_attr="keys", key_builder=build_key)
        async def fn(self, keys, market="ES"):
            return {pytest.KEY: 1, pytest.KEY_1: 2}

        await fn("self", keys=[pytest.KEY, pytest.KEY_1])
        assert await cache.exists(pytest.KEY + "_ES") is True
        assert await cache.exists(pytest.KEY_1 + "_ES") is True

    @pytest.mark.asyncio
    async def test_fn_with_args(self, cache):
        @multi_cached("keys")
        async def fn(keys, *args):
            assert len(args) == 1
            return {pytest.KEY: 1}

        await fn([pytest.KEY], "arg")
        assert await cache.exists(pytest.KEY) is True

    @pytest.mark.asyncio
    async def test_double_decorator(self, cache):
        def dummy_d(fn):
            async def wrapper(*args, **kwargs):
                await fn(*args, **kwargs)

            return wrapper

        @dummy_d
        @multi_cached("keys")
        async def fn(keys):
            return {pytest.KEY: 1}

        await fn([pytest.KEY])
        assert await cache.exists(pytest.KEY) is True

""" manage user """
from django.contrib.auth.decorators import login_required, permission_required
from django.core.paginator import Paginator
from django.shortcuts import get_object_or_404, redirect
from django.template.response import TemplateResponse
from django.utils.decorators import method_decorator
from django.views import View

from bookwyrm import forms, models
from bookwyrm.models.report import USER_PERMS
from bookwyrm.settings import PAGE_LENGTH


# pylint: disable=no-self-use
@method_decorator(login_required, name="dispatch")
@method_decorator(
    permission_required("bookwyrm.moderate_user", raise_exception=True),
    name="dispatch",
)
class UserAdminList(View):
    """admin view of users on this server"""

    def get(self, request, status="local"):
        """list of users"""
        filters = {}
        exclusions = {}
        if server := request.GET.get("server"):
            server = models.FederatedServer.objects.filter(server_name=server).first()
            filters["federated_server"] = server
            filters["federated_server__isnull"] = False

        if username := request.GET.get("username"):
            filters["username__icontains"] = username

        if email := request.GET.get("email"):
            filters["email__endswith"] = email

        filters["local"] = status in ["local", "deleted"]
        if status == "deleted":
            filters["deactivation_reason__icontains"] = "deletion"
        else:
            exclusions["deactivation_reason__icontains"] = "deletion"

        users = models.User.objects.filter(**filters).exclude(**exclusions)

        sort = request.GET.get("sort", "-created_date")
        sort_fields = [
            "created_date",
            "last_active_date",
            "username",
            "federated_server__server_name",
            "is_active",
        ]
        # pylint: disable=consider-using-f-string
        if sort in sort_fields + ["-{:s}".format(f) for f in sort_fields]:
            users = users.order_by(sort)

        paginated = Paginator(users, PAGE_LENGTH)
        page = paginated.get_page(request.GET.get("page"))
        data = {
            "users": page,
            "page_range": paginated.get_elided_page_range(
                page.number, on_each_side=2, on_ends=1
            ),
            "sort": sort,
            "server": server,
            "status": status,
        }
        return TemplateResponse(request, "settings/users/user_admin.html", data)


@method_decorator(login_required, name="dispatch")
@method_decorator(
    permission_required("bookwyrm.moderate_user", raise_exception=True),
    name="dispatch",
)
class UserAdmin(View):
    """moderate an individual user"""

    # pylint: disable=unused-argument
    def get(self, request, user_id, report_id=None):
        """user view"""
        user = get_object_or_404(models.User, id=user_id)
        data = {"user": user, "group_form": forms.UserGroupForm()}
        return TemplateResponse(request, "settings/users/user.html", data)

    def post(self, request, user_id, report_id=None):
        """update user group"""
        user = get_object_or_404(models.User, id=user_id)

        if request.POST.get("groups") == "":
            user.groups.set([])
            form = forms.UserGroupForm(instance=user)
        else:
            form = forms.UserGroupForm(request.POST, instance=user)
            if form.is_valid():
                form.save(request)

        if report_id:
            models.Report.record_action(report_id, USER_PERMS, request.user)

        data = {"user": user, "group_form": form}
        return TemplateResponse(request, "settings/users/user.html", data)


@method_decorator(login_required, name="dispatch")
@method_decorator(
    permission_required("bookwyrm.moderate_user", raise_exception=True),
    name="dispatch",
)
class ActivateUserAdmin(View):
    """activate a user manually"""

    # pylint: disable=unused-argument
    def post(self, request, user_id):
        """activate user"""
        user = get_object_or_404(models.User, id=user_id)
        user.reactivate()
        return redirect("settings-user", user.id)

import getpass
import logging
import typing
import uuid

from pymysql import err
import aiomysql
from sqlalchemy.dialects.mysql import pymysql
from sqlalchemy.engine.interfaces import Dialect, ExecutionContext
from sqlalchemy.engine.result import ResultMetaData, RowProxy
from sqlalchemy.sql import ClauseElement
from sqlalchemy.types import TypeEngine

from databases import exceptions
from databases.core import LOG_EXTRA, DatabaseURL
from databases.interfaces import ConnectionBackend, DatabaseBackend, TransactionBackend

logger = logging.getLogger("databases")


class MySQLBackend(DatabaseBackend):
    def __init__(
        self, database_url: typing.Union[DatabaseURL, str], **options: typing.Any
    ) -> None:
        self._database_url = DatabaseURL(database_url)
        self._options = options
        self._dialect = pymysql.dialect(paramstyle="pyformat")
        self._dialect.supports_native_decimal = True
        self._pool = None

    def _get_connection_kwargs(self) -> dict:
        url_options = self._database_url.options

        kwargs = {}
        min_size = url_options.get("min_size")
        max_size = url_options.get("max_size")
        ssl = url_options.get("ssl")

        if min_size is not None:
            kwargs["minsize"] = int(min_size)
        if max_size is not None:
            kwargs["maxsize"] = int(max_size)
        if ssl is not None:
            kwargs["ssl"] = {"true": True, "false": False}[ssl.lower()]

        for key, value in self._options.items():
            # Coerce 'min_size' and 'max_size' for consistency.
            if key == "min_size":
                key = "minsize"
            elif key == "max_size":
                key = "maxsize"
            kwargs[key] = value

        return kwargs

    async def connect(self) -> None:
        assert self._pool is None, "DatabaseBackend is already running"
        kwargs = self._get_connection_kwargs()
        self._pool = await aiomysql.create_pool(
            host=self._database_url.hostname,
            port=self._database_url.port or 3306,
            user=self._database_url.username or getpass.getuser(),
            password=self._database_url.password,
            db=self._database_url.database,
            autocommit=True,
            **kwargs,
        )

    async def disconnect(self) -> None:
        assert self._pool is not None, "DatabaseBackend is not running"
        self._pool.close()
        await self._pool.wait_closed()
        self._pool = None

    def connection(self) -> "MySQLConnection":
        return MySQLConnection(self, self._dialect)


class CompilationContext:
    def __init__(self, context: ExecutionContext):
        self.context = context


class MySQLConnection(ConnectionBackend):
    def __init__(self, database: MySQLBackend, dialect: Dialect):
        self._database = database
        self._dialect = dialect
        self._connection = None  # type: typing.Optional[aiomysql.Connection]

    async def acquire(self) -> None:
        assert self._connection is None, "Connection is already acquired"
        assert self._database._pool is not None, "DatabaseBackend is not running"
        self._connection = await self._database._pool.acquire()

    async def release(self) -> None:
        assert self._connection is not None, "Connection is not acquired"
        assert self._database._pool is not None, "DatabaseBackend is not running"
        await self._database._pool.release(self._connection)
        self._connection = None

    async def fetch_all(self, query: ClauseElement) -> typing.List[typing.Mapping]:
        assert self._connection is not None, "Connection is not acquired"
        query, args, context = self._compile(query)
        cursor = await self._connection.cursor()
        try:
            await cursor.execute(query, args)
            rows = await cursor.fetchall()
            metadata = ResultMetaData(context, cursor.description)
            return [
                RowProxy(metadata, row, metadata._processors, metadata._keymap)
                for row in rows
            ]
        except err.InterfaceError as error:
            raise exceptions.InterfaceError(str(query), None, error) from error
        except err.DataError as error:
            raise exceptions.DataError(str(query), None, error) from error
        except err.OperationalError as error:
            raise exceptions.OperationalError(str(query), None, error) from error
        except err.IntegrityError as error:
            raise exceptions.IntegrityError(str(query), None, error) from error
        except err.InternalError as error:
            raise exceptions.InternalError(str(query), None, error) from error
        except err.ProgrammingError as error:
            raise exceptions.ProgrammingError(str(query), None, error) from error
        except err.NotSupportedError as error:
            raise exceptions.NotSupportedError(str(query), None, error) from error
        except err.DatabaseError as error:
            raise exceptions.DatabaseError(str(query), None, error) from error
        finally:
            await cursor.close()

    async def fetch_one(self, query: ClauseElement) -> typing.Optional[typing.Mapping]:
        assert self._connection is not None, "Connection is not acquired"
        query, args, context = self._compile(query)
        cursor = await self._connection.cursor()
        try:
            await cursor.execute(query, args)
            row = await cursor.fetchone()
            if row is None:
                return None
            metadata = ResultMetaData(context, cursor.description)
            return RowProxy(metadata, row, metadata._processors, metadata._keymap)
        except err.InterfaceError as error:
            raise exceptions.InterfaceError(str(query), None, error) from error
        except err.DataError as error:
            raise exceptions.DataError(str(query), None, error) from error
        except err.OperationalError as error:
            raise exceptions.OperationalError(str(query), None, error) from error
        except err.IntegrityError as error:
            raise exceptions.IntegrityError(str(query), None, error) from error
        except err.InternalError as error:
            raise exceptions.InternalError(str(query), None, error) from error
        except err.ProgrammingError as error:
            raise exceptions.ProgrammingError(str(query), None, error) from error
        except err.NotSupportedError as error:
            raise exceptions.NotSupportedError(str(query), None, error) from error
        except err.DatabaseError as error:
            raise exceptions.DatabaseError(str(query), None, error) from error
        finally:
            await cursor.close()

    async def execute(self, query: ClauseElement) -> typing.Any:
        assert self._connection is not None, "Connection is not acquired"
        query, args, context = self._compile(query)
        cursor = await self._connection.cursor()
        try:
            await cursor.execute(query, args)
            if cursor.lastrowid == 0:
                return cursor.rowcount
            return cursor.lastrowid
        except err.InterfaceError as error:
            raise exceptions.InterfaceError(str(query), None, error) from error
        except err.DataError as error:
            raise exceptions.DataError(str(query), None, error) from error
        except err.OperationalError as error:
            raise exceptions.OperationalError(str(query), None, error) from error
        except err.IntegrityError as error:
            raise exceptions.IntegrityError(str(query), None, error) from error
        except err.InternalError as error:
            raise exceptions.InternalError(str(query), None, error) from error
        except err.ProgrammingError as error:
            raise exceptions.ProgrammingError(str(query), None, error) from error
        except err.NotSupportedError as error:
            raise exceptions.NotSupportedError(str(query), None, error) from error
        except err.DatabaseError as error:
            raise exceptions.DatabaseError(str(query), None, error) from error
        finally:
            await cursor.close()

    async def execute_many(self, queries: typing.List[ClauseElement]) -> None:
        assert self._connection is not None, "Connection is not acquired"
        cursor = await self._connection.cursor()
        try:
            for single_query in queries:
                single_query, args, context = self._compile(single_query)
                await cursor.execute(single_query, args)
        except err.InterfaceError as error:
            raise exceptions.InterfaceError(str(single_query), None, error) from error
        except err.DataError as error:
            raise exceptions.DataError(str(single_query), None, error) from error
        except err.OperationalError as error:
            raise exceptions.OperationalError(str(single_query), None, error) from error
        except err.IntegrityError as error:
            raise exceptions.IntegrityError(str(single_query), None, error) from error
        except err.InternalError as error:
            raise exceptions.InternalError(str(single_query), None, error) from error
        except err.ProgrammingError as error:
            raise exceptions.ProgrammingError(str(single_query), None, error) from error
        except err.NotSupportedError as error:
            raise exceptions.NotSupportedError(str(single_query), None, error) from error
        except err.DatabaseError as error:
            raise exceptions.DatabaseError(str(single_query), None, error) from error
        finally:
            await cursor.close()

    async def iterate(
        self, query: ClauseElement
    ) -> typing.AsyncGenerator[typing.Any, None]:
        assert self._connection is not None, "Connection is not acquired"
        query, args, context = self._compile(query)
        cursor = await self._connection.cursor()
        try:
            await cursor.execute(query, args)
            metadata = ResultMetaData(context, cursor.description)
            async for row in cursor:
                yield RowProxy(metadata, row, metadata._processors, metadata._keymap)
        except err.InterfaceError as error:
            raise exceptions.InterfaceError(str(query), None, error) from error
        except err.DataError as error:
            raise exceptions.DataError(str(query), None, error) from error
        except err.OperationalError as error:
            raise exceptions.OperationalError(str(query), None, error) from error
        except err.IntegrityError as error:
            raise exceptions.IntegrityError(str(query), None, error) from error
        except err.InternalError as error:
            raise exceptions.InternalError(str(query), None, error) from error
        except err.ProgrammingError as error:
            raise exceptions.ProgrammingError(str(query), None, error) from error
        except err.NotSupportedError as error:
            raise exceptions.NotSupportedError(str(query), None, error) from error
        except err.DatabaseError as error:
            raise exceptions.DatabaseError(str(query), None, error) from error
        finally:
            await cursor.close()

    def transaction(self) -> TransactionBackend:
        return MySQLTransaction(self)

    def _compile(
        self, query: ClauseElement
    ) -> typing.Tuple[str, dict, CompilationContext]:
        compiled = query.compile(dialect=self._dialect)
        args = compiled.construct_params()
        for key, val in args.items():
            if key in compiled._bind_processors:
                args[key] = compiled._bind_processors[key](val)

        execution_context = self._dialect.execution_ctx_cls()
        execution_context.dialect = self._dialect
        execution_context.result_column_struct = (
            compiled._result_columns,
            compiled._ordered_columns,
            compiled._textual_ordered_columns,
        )

        query_message = compiled.string.replace(" \n", " ").replace("\n", " ")
        logger.debug("Query: %s Args: %s", query_message, repr(args), extra=LOG_EXTRA)
        return compiled.string, args, CompilationContext(execution_context)

    @property
    def raw_connection(self) -> aiomysql.connection.Connection:
        assert self._connection is not None, "Connection is not acquired"
        return self._connection


class MySQLTransaction(TransactionBackend):
    def __init__(self, connection: MySQLConnection):
        self._connection = connection
        self._is_root = False
        self._savepoint_name = ""

    async def start(self, is_root: bool) -> None:
        assert self._connection._connection is not None, "Connection is not acquired"
        self._is_root = is_root
        if self._is_root:
            await self._connection._connection.begin()
        else:
            id = str(uuid.uuid4()).replace("-", "_")
            self._savepoint_name = f"STARLETTE_SAVEPOINT_{id}"
            cursor = await self._connection._connection.cursor()
            try:
                await cursor.execute(f"SAVEPOINT {self._savepoint_name}")
            finally:
                await cursor.close()

    async def commit(self) -> None:
        assert self._connection._connection is not None, "Connection is not acquired"
        if self._is_root:
            await self._connection._connection.commit()
        else:
            cursor = await self._connection._connection.cursor()
            try:
                await cursor.execute(f"RELEASE SAVEPOINT {self._savepoint_name}")
            finally:
                await cursor.close()

    async def rollback(self) -> None:
        assert self._connection._connection is not None, "Connection is not acquired"
        if self._is_root:
            await self._connection._connection.rollback()
        else:
            cursor = await self._connection._connection.cursor()
            try:
                await cursor.execute(f"ROLLBACK TO SAVEPOINT {self._savepoint_name}")
            finally:
                await cursor.close()

