# compute as fast as possible using dynamic memory
primes = [2]
def isPrime(n):
  if n <= 1:
    return False
  if n in primes:
    return True
  for i in range(primes[-1], n):
    isPrime(i)
  for p in primes:
    if n % p == 0:
      return False
  primes.append(n)
  return True

